        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 500000,
                    satisfaction: 4.1,
                    directBookingRate: 0.24,
                    totalRoomRevenue: 0,
                    totalGop: 0,
                    cumulativeRevpar: 0,
                    revparHistory: [],
                    gopparHistory: [],
                    occupancyHistory: [],
                    satisfactionHistory: [],
                    adrHistory: [],
                    netRevparHistory: [],
                    trevparHistory: [],
                    revparIndexHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    adr: 112,
                    otaPct: 58,
                    marketingBudget: 3000,
                    serviceInvestment: 5000,
                    groupAccept: true
                };
            }
            this._syncControlsFromDecisions(state);
            this._updateBriefing(state);
            this._bindPanelRepaint();
        }

        // Put the player own decisions back into the controls on resume. The framework
        // restoreInputValues() maps a decision key to <key>, <key>Input, <key>Select, so
        // only adr matched a control id here and the other four silently reverted to the
        // authored defaults. EQIL section 14 item 3.
        _syncControlsFromDecisions(state) {
            var d = (state && state.decisions) || {};
            var map = {
                adr: 'adrInput',
                otaPct: 'otaInput',
                marketingBudget: 'marketingInput',
                serviceInvestment: 'serviceInput'
            };
            Object.keys(map).forEach(function(k) {
                var el = document.getElementById(map[k]);
                if (el && d[k] !== undefined && d[k] !== null) el.value = String(d[k]);
            });
            var g = document.getElementById('groupSelect');
            if (g && d.groupAccept !== undefined && d.groupAccept !== null) {
                g.value = d.groupAccept ? 'accept' : 'decline';
            }
        }

        // The round panel is repainted from the framework event bus, never from a timer
        // inside calculateResults. period:submitted is emitted after the period has
        // advanced, so the state handed to the callback is the round about to be decided.
        // This also repaints correctly on undo, on resume and on a language switch.
        _bindPanelRepaint() {
            if (this._panelBound) return;
            var sim = window.mySimulation;
            var bus = sim && sim.eventBus;
            if (!bus || typeof bus.on !== 'function') return;
            this._panelBound = true;
            var self = this;
            ['period:submitted', 'period:undone', 'state:loaded', 'language:changed'].forEach(function(evt) {
                bus.on(evt, function() {
                    var s = window.mySimulation && window.mySimulation.state;
                    if (s) self._updateBriefing(s);
                });
            });
        }

        // Translation lookup that tolerates a missing table and a missing key.
        _t(key, fallback) {
            try {
                var s = window.mySimulation.t(key);
                if (s && s !== key) return s;
            } catch (e) {}
            return fallback;
        }

        validateDecisions(decisions) {
            var adrInput = document.getElementById('adrInput');
            if (adrInput) decisions.adr = parseFloat(adrInput.value);

            var otaInput = document.getElementById('otaInput');
            if (otaInput) decisions.otaPct = parseFloat(otaInput.value);

            var marketingInput = document.getElementById('marketingInput');
            if (marketingInput) decisions.marketingBudget = parseFloat(marketingInput.value);

            var serviceInput = document.getElementById('serviceInput');
            if (serviceInput) decisions.serviceInvestment = parseFloat(serviceInput.value);

            var groupSelect = document.getElementById('groupSelect');
            if (groupSelect) decisions.groupAccept = (groupSelect.value === 'accept');

            if (!decisions.adr || decisions.adr < 60 || decisions.adr > 250) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('adr_warning'), 'warning'
                );
                return false;
            }

            if (decisions.otaPct === undefined || decisions.otaPct < 0 || decisions.otaPct > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('ota_warning'), 'warning'
                );
                return false;
            }

            if (decisions.marketingBudget === undefined || decisions.marketingBudget < 0 || decisions.marketingBudget > 20000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('marketing_warning'), 'warning'
                );
                return false;
            }

            if (decisions.serviceInvestment === undefined || decisions.serviceInvestment < 0 || decisions.serviceInvestment > 20000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('service_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var monthIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[monthIdx];
            var arn = this.AVAILABLE_ROOM_NIGHTS;

            // Group booking
            var groupRN = 0;
            var groupRevenue = 0;
            var groupFbRevenue = 0;
            if (d.groupAccept && round.groupOffer) {
                groupRN = round.groupOffer.rooms * round.groupOffer.nights;
                groupRevenue = groupRN * round.groupOffer.rate;
                groupFbRevenue = round.groupOffer.fbRevenue || 0;
            }

            var remainingRN = arn - groupRN;

            // Price elasticity
            var priceEffect = Math.pow(this.BASE_ADR / d.adr, 1.2);
            priceEffect = Math.max(0.4, Math.min(1.6, priceEffect));

            // Satisfaction multiplier
            var satMultiplier = 1 + (ds.satisfaction - 4.0) * 0.25;

            // OTA billboard effect
            var otaBillboard = 1 + (d.otaPct / 100 - 0.30) * 0.12;
            otaBillboard = Math.max(0.85, Math.min(1.15, otaBillboard));

            // Direct booking demand bonus from accumulated loyalty investment
            var directBonus = 1 + (ds.directBookingRate - 0.24) * 0.15;

            // Competitive shock from Month 9 onward (new Marriott)
            var compShock = monthIdx >= 8 ? 0.88 : 1.0;
            // Mitigate shock if satisfaction is high
            if (monthIdx >= 8 && ds.satisfaction >= 4.3) {
                compShock += (ds.satisfaction - 4.3) * 0.10;
                compShock = Math.min(compShock, 0.97);
            }

            // Total demand multiplier
            var demandMultiplier = priceEffect * satMultiplier * otaBillboard * directBonus * compShock;

            // Stochastic noise (+/- 8%)
            var noise = 1 + (Math.random() - 0.5) * 0.16;
            demandMultiplier *= noise;

            // Base transient demand
            var baseTransientDemand = round.baseDemandRate * arn;
            var adjustedDemand = Math.round(baseTransientDemand * demandMultiplier);

            // Actual transient room nights
            var transientRN = Math.min(adjustedDemand, remainingRN);
            transientRN = Math.max(0, transientRN);

            // Total room nights
            var totalRN = transientRN + groupRN;
            var occupancyRate = totalRN / arn;

            // Revenue
            var transientRoomRevenue = transientRN * d.adr;
            var totalRoomRevenue = transientRoomRevenue + groupRevenue;

            // Blended ADR
            var blendedADR = totalRN > 0 ? totalRoomRevenue / totalRN : 0;

            // RevPAR
            var revpar = totalRoomRevenue / arn;

            // Distribution costs
            var otaFraction = d.otaPct / 100;
            var otaRN = Math.round(transientRN * otaFraction);
            var directRN = transientRN - otaRN;
            var otaCommission = otaRN * d.adr * this.OTA_COMMISSION_RATE;
            var directCost = directRN * this.DIRECT_COST_PER_RN;
            var totalDistCost = otaCommission + directCost;

            // Net room revenue and Net RevPAR
            var netRoomRevenue = totalRoomRevenue - totalDistCost;
            var netRevpar = netRoomRevenue / arn;

            // F&B and ancillary revenue
            var fbPerOccRoom = 28 * (1 + (ds.satisfaction - 4.0) * 0.15);
            var fbRevenue = Math.round(totalRN * fbPerOccRoom) + groupFbRevenue;

            // TRevPAR
            var trevpar = (totalRoomRevenue + fbRevenue) / arn;

            // Operating costs
            var variableCosts = totalRN * this.VARIABLE_COST_PER_RN;
            var totalCosts = this.BASE_FIXED_COSTS + variableCosts + totalDistCost + d.marketingBudget + d.serviceInvestment;

            // GOP and GOPPAR
            var gop = totalRoomRevenue + fbRevenue - totalCosts;
            var goppar = gop / arn;

            // Update satisfaction (partial lag)
            var satChange = (d.serviceInvestment - 5000) / 55000;
            // Overcrowding penalty
            if (occupancyRate > 0.90) {
                satChange -= (occupancyRate - 0.90) * 0.6;
            }
            // Small random factor
            satChange += (Math.random() - 0.5) * 0.04;
            ds.satisfaction = Math.max(3.0, Math.min(5.0,
                Math.round((ds.satisfaction + satChange) * 100) / 100));

            // Update direct booking rate (lagged effect of marketing)
            var directBoost = (d.marketingBudget / 120000) * 0.025;
            // Natural decay toward OTA dependency if not investing
            var directDecay = d.marketingBudget < 2000 ? 0.008 : 0.002;
            ds.directBookingRate = Math.max(0.10, Math.min(0.70,
                Math.round((ds.directBookingRate + directBoost - directDecay) * 1000) / 1000));

            // Accumulate totals
            ds.cash += Math.round(gop);
            ds.totalRoomRevenue += Math.round(totalRoomRevenue);
            ds.totalGop += Math.round(gop);

            // Push to history arrays
            ds.revparHistory.push(Math.round(revpar * 100) / 100);
            ds.gopparHistory.push(Math.round(goppar * 100) / 100);
            ds.occupancyHistory.push(Math.round(occupancyRate * 1000) / 10);
            ds.satisfactionHistory.push(ds.satisfaction);
            ds.adrHistory.push(Math.round(blendedADR * 100) / 100);
            ds.netRevparHistory.push(Math.round(netRevpar * 100) / 100);

            // Competitor RevPAR for index calculation
            var compRevpar = round.competitorADR * (round.competitorOcc / 100);
            var revparIndex = compRevpar > 0 ? Math.round((revpar / compRevpar) * 100) : 100;

            // v1.1.0 fix: track TRevPAR & RPI, then persist composite where Express reporting reads it.
            // results_utils.php express_resolveDomainScore(): performance.overallScore, then top-level score.
            ds.trevparHistory.push(Math.round(trevpar * 100) / 100);
            ds.revparIndexHistory.push(revparIndex);
            var composite = this._crmi(ds.revparHistory, ds.netRevparHistory, ds.satisfactionHistory, ds.revparIndexHistory, ds.trevparHistory).crmi;
            ds.score = composite;
            if (!ds.performance || typeof ds.performance !== 'object') ds.performance = {};
            ds.performance.overallScore = composite;

            return {
                period: state.currentPeriod,
                occupancy: Math.round(occupancyRate * 1000) / 10,
                adr: Math.round(blendedADR * 100) / 100,
                revpar: Math.round(revpar * 100) / 100,
                netRevpar: Math.round(netRevpar * 100) / 100,
                trevpar: Math.round(trevpar * 100) / 100,
                goppar: Math.round(goppar * 100) / 100,
                gop: Math.round(gop),
                roomRevenue: Math.round(totalRoomRevenue),
                fbRevenue: Math.round(fbRevenue),
                distCost: Math.round(totalDistCost),
                satisfaction: ds.satisfaction,
                directRate: ds.directBookingRate,
                revparIndex: revparIndex,
                groupAccepted: d.groupAccept,
                groupRN: groupRN,
                transientRN: transientRN,
                cash: Math.round(ds.cash)
            };
        }

