        _crmi(revpars, netRevpars, satisfactions, revparIndexes, trevpars) {
            var avg = function(a){ return a.length ? a.reduce(function(s,v){ return s + v; }, 0) / a.length : 0; };
            var avgRevpar = avg(revpars);
            var avgRevparIndex = avg(revparIndexes);
            var netRevparAvg = avg(netRevpars);
            var avgSatisfaction = avg(satisfactions);
            var trevparAvg = avg(trevpars);
            var revparGrowth = avgRevpar > 0 ? ((avgRevpar - 68) / 68 * 100) : 0;
            var revparScore = Math.min(30, Math.max(0, revparGrowth * 1.0));
            var indexScore = Math.min(25, Math.max(0, (avgRevparIndex - 80) * 1.25));
            var netRevparScore = Math.min(20, Math.max(0, (netRevparAvg - 40) * 0.5));
            var satisfactionScore = Math.min(10, Math.max(0, (avgSatisfaction - 3.5) * 6.67));
            var trevparScore = Math.min(15, Math.max(0, (trevparAvg - 80) * 0.375));
            var crmi = Math.round(revparScore + indexScore + netRevparScore + trevparScore + satisfactionScore);
            return { crmi: crmi, avgRevpar: avgRevpar, avgRevparIndex: avgRevparIndex,
                     netRevparAvg: netRevparAvg, avgSatisfaction: avgSatisfaction, trevparAvg: trevparAvg,
                     revparGrowth: revparGrowth };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = function(k) { return window.mySimulation.t(k); };
            var mapv = function(key, dflt){ return history.map(function(r){ return r.results ? (r.results[key] != null ? r.results[key] : dflt) : dflt; }); };
            var revpars = mapv('revpar', 0);
            var goppars = mapv('goppar', 0);
            var satisfactions = mapv('satisfaction', 0);
            var revparIndexes = mapv('revparIndex', 100);
            var netRevpars = mapv('netRevpar', 0);
            var trevpars = mapv('trevpar', 0);

            var m = this._crmi(revpars, netRevpars, satisfactions, revparIndexes, trevpars);
            var avgGoppar = goppars.reduce(function(s, v){ return s + v; }, 0) / goppars.length;
            var finalSatisfaction = satisfactions[satisfactions.length - 1];
            var crmi = m.crmi;

            var performanceId = 'apprentice', gradeKey = 'grade_apprentice';
            if (crmi >= 75) { performanceId = 'master'; gradeKey = 'grade_master'; }
            else if (crmi >= 55) { performanceId = 'senior'; gradeKey = 'grade_senior'; }
            else if (crmi >= 35) { performanceId = 'analyst'; gradeKey = 'grade_analyst'; }

            var insights = [];
            if (m.avgRevpar > 90) insights.push(t('insight_revpar_high'));
            else if (m.avgRevpar < 68) insights.push(t('insight_revpar_low'));
            if (m.avgRevparIndex > 110) insights.push(t('insight_rpi_high'));
            else if (m.avgRevparIndex < 95) insights.push(t('insight_rpi_low'));
            if (finalSatisfaction >= 4.3) insights.push(t('insight_sat_high'));
            else if (finalSatisfaction < 3.8) insights.push(t('insight_sat_low'));
            if (m.netRevparAvg > 60) insights.push(t('insight_net_high'));
            if (insights.length === 0) insights.push(t('insight_solid'));

            return {
                crmi: crmi,
                overallScore: crmi,
                score: crmi,
                avgRevpar: Math.round(m.avgRevpar * 100) / 100,
                avgGoppar: Math.round(avgGoppar * 100) / 100,
                avgRevparIndex: Math.round(m.avgRevparIndex),
                avgSatisfaction: Math.round(m.avgSatisfaction * 100) / 100,
                revparGrowth: Math.round(m.revparGrowth * 10) / 10,
                totalScore: crmi,
                performanceId: performanceId,
                performance: t(gradeKey),
                performanceLabel: t(gradeKey),
                beatMarket: crmi >= 55,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = function(k){ return window.mySimulation.t(k); };
            var s = summary || {};
            var score = (typeof s.crmi === 'number') ? s.crmi : 0;
            var grade = s.performance || '';
            var beat = !!s.beatMarket;
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var badgeClass = beat ? 'hrm-cm-badge-pass' : 'hrm-cm-badge-miss';
            var badgeText = beat ? t('cm_badge_beat') : t('cm_badge_missed');
            var kpi = function(label, val){ return '<div class="hrm-cm-kpi"><div class="hrm-cm-kpi-val">' + val + '</div><div class="hrm-cm-kpi-label">' + label + '</div></div>'; };
            var money = function(v){ return '$' + Math.round(v).toLocaleString(); };
            var insightHtml = '';
            insights.forEach(function(it){ insightHtml += '<li>' + it + '</li>'; });
            return '' +
              '<div class="hrm-cm">' +
                '<div class="hrm-cm-scoreblock">' +
                  '<div class="hrm-cm-scorenum">' + score + '<span class="hrm-cm-scoremax">/100</span></div>' +
                  '<div class="hrm-cm-scorelabel">' + t('cm_score_label') + '</div>' +
                  '<div class="hrm-cm-grade">' + grade + '</div>' +
                  '<span class="hrm-cm-badge ' + badgeClass + '">' + badgeText + '</span>' +
                '</div>' +
                '<div class="hrm-cm-kpis">' +
                  kpi(t('cm_revpar_label'), money(s.avgRevpar || 0)) +
                  kpi(t('cm_goppar_label'), money(s.avgGoppar || 0)) +
                  kpi(t('cm_rpi_label'), (s.avgRevparIndex || 0)) +
                  kpi(t('cm_sat_label'), (s.avgSatisfaction || 0).toFixed(1) + ' / 5.0') +
                '</div>' +
                (insightHtml ? '<div class="hrm-cm-insights"><h6>' + t('cm_insights_title') + '</h6><ul>' + insightHtml + '</ul></div>' : '') +
                '<div class="hrm-cm-footer">' + t('cm_footer') + '</div>' +
              '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.goppar < 0) return window.mySimulation.t('hint_negative_gop');
            if (results.revparIndex < 90) return window.mySimulation.t('hint_low_index');
            if (results.occupancy > 92) return window.mySimulation.t('hint_overcrowding');
            if (results.occupancy < 45) return window.mySimulation.t('hint_low_occupancy');
            if (state.domainState.satisfaction < 3.8) return window.mySimulation.t('hint_low_satisfaction');
            if (state.domainState.directBookingRate < 0.18) return window.mySimulation.t('hint_ota_dependency');
            if (results.revpar > 100) return window.mySimulation.t('hint_strong_revpar');
            return null;
        }

