        // Language, in the order the platform settles it: the live vc_i18n value first,
        // then the framework option, then the document. Matches the 2064 v2 pattern.
        _lang() {
            try {
                if (window.vcI18n && window.vcI18n._lang) return window.vcI18n._lang.substring(0, 2);
            } catch (e) {}
            try {
                if (window.mySimulation && window.mySimulation.options && window.mySimulation.options.language) {
                    return window.mySimulation.options.language.substring(0, 2);
                }
            } catch (e) {}
            try {
                var htmlLang = document.documentElement.lang;
                if (htmlLang && htmlLang.substring(0, 2) === 'es') return 'es';
            } catch (e) {}
            return 'en';
        }

        _setPanelsVisible(on) {
            ['decisionsPanel', 'groupOfferPanel', 'eqilBtnRow'].forEach(function(id) {
                var el = document.getElementById(id);
                if (el) el.style.display = on ? '' : 'none';
            });
        }

        _updateBriefing(state) {
            var period = (state && state.currentPeriod) || 1;

            // Past the last round there is nothing left to decide. Hide the decision
            // block, the offer and the button row instead of leaving a stale panel and a
            // live-looking form on screen. EQIL section 14 item 4.
            if (period > this.ROUNDS.length) {
                this._setPanelsVisible(false);
                return;
            }
            this._setPanelsVisible(true);

            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = this._lang();

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var seasonName = this._t('season_' + round.season.toLowerCase(), round.season);
                var seasonTag = '<strong>' +
                    this._t('season_tag', '{season} Season').split('{season}').join(seasonName) +
                    '</strong> — ';
                briefEl.innerHTML = seasonTag + (lang === 'es' ? round.briefingEs : round.briefing);
            }

            var groupPanel = document.getElementById('groupOfferPanel');
            var groupText = document.getElementById('groupOfferText');
            if (groupPanel && groupText && round.groupOffer) {
                groupPanel.style.display = 'block';
                var offer = round.groupOffer;
                var revenueEst = offer.rooms * offer.nights * offer.rate + offer.fbRevenue;
                var offerDesc = lang === 'es' ? offer.descEs : offer.desc;
                groupText.innerHTML = offerDesc + '<br><strong>' +
                    this._t('estimated_revenue', 'Estimated revenue') +
                    ': $' + revenueEst.toLocaleString() + '</strong>';
            }

            // These are THIS round competitor figures, and they are the denominator of
            // this round RPI. The old copy called them the prior month, which they never were.
            var compPanel = document.getElementById('compIntelText');
            if (compPanel) {
                var setRevpar = Math.round(round.competitorADR * round.competitorOcc / 100);
                compPanel.innerHTML = this._t('comp_intel_line',
                        'Competitive set this month: Avg ADR <strong>${adr}</strong> | Avg Occupancy <strong>{occ}%</strong> | Set RevPAR: <strong>${revpar}</strong>')
                    .split('{adr}').join(round.competitorADR)
                    .split('{occ}').join(round.competitorOcc)
                    .split('{revpar}').join(setRevpar);
            }
        }
    }

